let db = @@GRAPH@@
let imported = graph_import_documents(db,{"batch_id":"date-role","files":[{"path":@@CSV@@,"normalization_profile":{"currency":"USD"}}]})
let snapshot = graph_snapshot(db)
expect snapshot["nodes"][0]["data"]["normalization"]["fields"][0]["value"]["kind"] == "money"
expect snapshot["nodes"][0]["data"]["normalization"]["fields"][0]["value"]["canonical"] == "15400"

